        assert np.array_equal(raw[0],ctx['raw_phi']) and np.array_equal(raw[1],ctx['test_phi']);mu=raw[0].mean(0);sd=raw[0].std(0);sd[sd<1e-8]=1;P=(raw[0]-mu)/sd;Q=(raw[1]-mu)/sd;flags=(d['F'][te,0]<d['F'][tr,0].min())|(d['F'][te,0]>d['F'][tr,0].max());assert np.array_equal(flags,ctx['guard_flags']) and np.array_equal(ctx['fallback'],base['fallback']);assert len(rec['models'])==4
        for row in rec['models']:
            ci=row['index'];cfg=p['configs'][ci];assert row['config']==cfg and sha(row['path'])==row['sha256'];m=np.load(row['path']);assert np.array_equal(m['mean'],mu) and np.array_equal(m['std'],sd) and int(m['config_index'])==ci;positive=(len(tr)-sum(y[tr]>=20))/sum(y[tr]>=20);assert m['training_positive_weight']==positive;w=m['gate_weight'];bias=float(m['gate_bias']);assert np.isfinite(w).all() and np.isfinite(bias);initial,_=objective(np.zeros(5),-2,P,expert[0][0],expert[1][0],y[tr],cfg);value,grad=objective(w,bias,P,expert[0][0],expert[1][0],y[tr],cfg);assert np.isclose(initial,row['initial_objective'],atol=1e-10,rtol=1e-10) and np.isclose(value,row['final_objective'],atol=1e-10,rtol=1e-10) and value<=initial+1e-10;assert np.allclose(grad,m['gradient'],atol=1e-8,rtol=1e-8) and np.isclose(np.max(np.abs(grad)),row['max_gradient'],atol=1e-8,rtol=1e-8)
